package com.problems.strings;

public class FindTheDifference {

    static void main() {
        System.out.println(findTheDifference("abcd", "abcde"));
        System.out.println(findTheDifference("", "y"));
        System.out.println(findTheDifference("", ""));
    }

    public static char findTheDifference(final String s, final String t) {
        final int[] resultsS = new int[26];
        final int[] resultsT = new int[26];

        if (t.length() == 1) {
            return t.charAt(0);
        }

        for (int i = 0; i < s.length(); i++) {
            resultsS[s.charAt(i) - 'a']++;
        }

        for (int i = 0; i < t.length(); i++) {
            resultsT[t.charAt(i) - 'a']++;
        }

        int i = 0;
        while (resultsS[i] == resultsT[i]) {
            i++;
        }

        return (char) ('a' + i);
    }
}
